    fillActors(solidBatch, glassBatch, world, near);
    upload(solidBuf, solidBatch, gl.DYNAMIC_DRAW);
    upload(glassBuf, glassBatch, gl.DYNAMIC_DRAW);
    drawBuffer(solidBuf);
    gl.depthMask(false);
    drawBuffer(glassBuf);
    gl.depthMask(true);

