    vignette.addColorStop(1, 'rgba(0,0,0,0.25)');
    hud.fillStyle = vignette;
    hud.fillRect(0, 0, w, h);
    if (showHud) drawHud(hud, world, cam, w, h);
    if (overlay) overlay(hud, w, h);
  }

  return { draw };
