      batch.disc(cx, cz, b.height + 0.8, Math.min(b.w, b.h) * 0.3, rgb('#4d555c'));
      batch.disc(cx, cz, b.height + 1.2, Math.min(b.w, b.h) * 0.27, rgb('#f2c94c'), 1, Math.min(b.w, b.h) * 0.24);
